<?php
declare(strict_types=1);
namespace TNL\Mail;
require_once __DIR__.'/Reception.php';
final class ReceptionWorker {
 public static function poll(\PDO $db,string $storage,bool $force=false): array {
  Reception::init($db);$owner=Reception::owner($db);if($owner==='')return ['enabled'=>false];$lock=fopen($storage.'/reception-sync.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))return ['busy'=>true];$imap=null;
  try{$q=$db->prepare('SELECT * FROM reception_sync WHERE mailbox=?');$q->execute([$owner]);$state=$q->fetch(\PDO::FETCH_ASSOC);if(!$state)throw new \RuntimeException('Activa la recepción para crear el cursor.');if(!$force&&time()-(int)$state['last_poll']<300)return ['due'=>false];$db->prepare('UPDATE reception_sync SET last_poll=? WHERE mailbox=?')->execute([time(),$owner]);$account=(new ExternalAccount($db,$storage))->load($owner);if(!$account)throw new \RuntimeException('Buzón compartido no disponible.');$imap=new ImapClient($account);$imap->connect();$batch=$imap->uidsSince((int)$state['next_uid']);if($batch['validity']!==(int)$state['validity'])throw new \RuntimeException('Cambió UIDVALIDITY. Reactiva el buzón para evitar importar correo antiguo.');$processed=0;$deadline=microtime(true)+18;
   $skipped=0;foreach($batch['uids'] as $uid){if(microtime(true)>$deadline)break;try{$message=$imap->read($uid);$result=Reception::ingest($db,$owner,(int)$state['validity'],$uid,$message,$storage);if(!empty($result['auto_reply'])&&strcasecmp($result['sender'],$account['email'])!==0)self::autoReply($db,$owner,$account,$result,$storage);}catch(\Throwable $e){if(!$e instanceof \InvalidArgumentException&&!str_contains($e->getMessage(),'límite de lectura')&&!str_contains($e->getMessage(),'demasiado grande'))throw $e;$db->prepare('INSERT OR IGNORE INTO reception_errors VALUES(?,?,?,?,?)')->execute([$owner,(int)$state['validity'],$uid,substr($e->getMessage(),0,250),gmdate('c')]);$skipped++;}$db->prepare('UPDATE reception_sync SET next_uid=?,last_error=? WHERE mailbox=?')->execute([$uid+1,'',$owner]);$processed++;}return ['processed'=>$processed,'skipped'=>$skipped,'pending_batch'=>count($batch['uids'])>$processed];
  }catch(\Throwable $e){$db->prepare('UPDATE reception_sync SET last_error=? WHERE mailbox=?')->execute([substr($e->getMessage(),0,300),$owner]);return ['error'=>'No se completó la sincronización. Revisa Recepción en administración.'];}finally{if($imap)$imap->close();flock($lock,LOCK_UN);fclose($lock);}
 }
 public static function autoReply(\PDO $db,string $owner,array $account,array $result,string $storage,?\Closure $transport=null): void {
  $q=$db->prepare('SELECT 1 FROM reception_contacts WHERE mailbox=? AND sender=?');$q->execute([$owner,$result['sender']]);if($q->fetchColumn())return;$q=$db->prepare('SELECT count(*) FROM reception_contacts WHERE created_at>?');$q->execute([gmdate('c',time()-3600)]);if((int)$q->fetchColumn()>=10)return;
  $db->prepare('INSERT OR IGNORE INTO reception_contacts VALUES(?,?,?,?)')->execute([$owner,$result['sender'],'attempting',gmdate('c')]);if($db->query('SELECT changes()')->fetchColumn()!=1)return;
  $body='<p>Gracias por comunicarte con nosotros.</p><p>Este es un correo automático. Hemos detectado que es la primera vez que nos escribes. ¿Con qué área o persona quieres contactar?</p><p>Responde a este correo con el nombre, usuario o dirección interna. Pronto recibirás una respuesta.</p><ul>';foreach(array_slice(Reception::staff($db),0,40) as $u)$body.='<li>'.htmlspecialchars($u['display_name'].' · '.$u['job_title'].' · '.$u['internal_address'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</li>';$body.='</ul><p>Ejemplo: josegaldamez@miempresa.com o José Galdamez Contador.</p>';
  $thread=ReplyComposer::thread($result['headers']);$thread['route_marker']=Reception::marker($result['token'],$storage);$thread['route_identity']='Recepción automática';$thread['auto_reply']=true;$subject='Re: '.substr(preg_replace('/[\r\n]+/',' ',$result['headers']['subject']??'Tu consulta'),0,170);
  try{$mid=$transport?$transport($result['sender'],$subject,$body,$thread):ExternalMail::send($account,$result['sender'],$subject,$body,null,$thread,'html');Reception::link($db,$owner,$mid,$result['token']);$state='accepted';}catch(\Throwable $e){$state='unconfirmed';}$db->prepare('UPDATE reception_contacts SET state=? WHERE mailbox=? AND sender=?')->execute([$state,$owner,$result['sender']]);
 }
}
if(PHP_SAPI==='cli'&&realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){require dirname(__DIR__,2).'/bootstrap.php';echo json_encode(ReceptionWorker::poll(\tnl_db(),\tnl_path('storage'))).PHP_EOL;}
